    "id": "tour_l1_step2_en",
    "speaker": "VEGA",
    "lang": "en",
    "filename": "vega_en_fe99e13cddf9da745305.mp3",
    "canonicalText": "Great move! You saw the cube resize in the center. Now look at SOLAR ARRAYS / EPS below on the left. They generate electricity so your ship never dies in the dark like Icarus-1. Click any power system to deploy the wings!"
