    "id": "hud_cml4_cadet_en",
    "speaker": "VEGA",
    "lang": "en",
    "filename": "vega_en_442ec1800bd2535ed8b7.mp3",
    "canonicalText": "Every drop of hydrazine counts, Orion. Adjust the 4 tank sliders on the left without turning the center rocket red, then click \"COMMIT & VALIDATE\" on the right."
