    "speaker": "VEGA",
    "lang": "en",
    "filename": "vega_en_8bd87214ef0e112fa86e.mp3",
    "canonicalText": "Engines smoking in Florida, Orion! Resolve the 3 crises on the right panel, then click the red OMEGA ALERT button to face the next chapter!"
